func Use(opener ResourceOpener, input string) error {
	var r Resource
	var err error
	for {
		r, err = opener()
		if err == nil {
			break
		}
		var te TransientError
		if errors.As(err, &te) {
			continue
		}
		return err
	}
	defer r.Close()
	defer func() {
		if p := recover(); p != nil {
			if fe, ok := p.(FrobError); ok {
				r.Defrob(fe.defrobTag)
			}
		}
	}()
	r.Frob(input)
	return nil
}
```

