package erratum

import "errors"

// Use opens a resource via opener, calls Frob(input) on it, and ensures the
// resource is closed exactly once. Transient open errors are retried; a panic
// from Frob is recovered, and if it is a FrobError the resource is Defrobbed
// with the error's defrobTag before closing.
func Use(opener ResourceOpener, input string) (err error) {
	var resource Resource
	for {
		resource, err = opener()
		if err == nil {
			break
		}
		var te TransientError
		if errors.As(err, &te) {
			continue
		}
		return err
	}

	defer resource.Close()
	defer func() {
		p := recover()
		if p == nil {
			return
		}
		if fe, ok := p.(FrobError); ok {
			resource.Defrob(fe.defrobTag)
		}
		if e, ok := p.(error); ok {
			err = e
		} else {
			panic(p)
		}
	}()

	resource.Frob(input)
	return nil
}
```

