package erratum

import "errors"

// Use opens a resource via opener, calls Frob(input) on it, and ensures the
// resource is closed exactly once in all cases.
//
// If opener fails with a TransientError the open is retried; any other error
// is returned. If Frob panics, the panic is recovered: a FrobError is
// defrobbed (using its defrobTag) before the resource is closed, and the
// recovered error is returned.
func Use(opener ResourceOpener, input string) (err error) {
	var resource Resource
	for {
		resource, err = opener()
		if err == nil {
			break
		}
		var te TransientError
		if errors.As(err, &te) {
			// Resource is temporarily unavailable; retry.
			continue
		}
		return err
	}

	// Close exactly once, in all cases.
	defer resource.Close()

	// Recover from a panic in Frob. Defrob must run before Close, so this
	// deferred function (registered after Close) runs first.
	defer func() {
		p := recover()
		if p == nil {
			return
		}
		if fe, ok := p.(FrobError); ok {
			resource.Defrob(fe.defrobTag)
		}
		if e, ok := p.(error); ok {
			err = e
		} else {
			// The panicked value is not an error; propagate it.
			panic(p)
		}
	}()

	resource.Frob(input)
	return nil
}
